Get-ChildItem "$env:USERPROFILE\.copilot\session-state" -Directory | ForEach-Object {
  $wsPath = Join-Path $_.FullName "workspace.yaml"
  if (Test-Path $wsPath) {
    $content = Get-Content $wsPath -Raw
    if ($content -match "rpothin-fuzzy-robot") {
      Write-Output "=== $($_.Name) ==="
      Write-Output $content
    }
  }
}
